import { Accessor, createEffect, createMemo, createRoot, createSignal, on, onCleanup, onMount, Setter } from "solid-js";

export type Mutator<T> = (mutator: (value: T) => void) => void;

export type ArraySignal<T> = [value: Accessor<T[]>, mutate: Mutator<T[]>];

/**
 * Creates a mutable array reactive state with a setter and mutator
 * ```ts
 * const [state, mutate] = createArraySignal<string>(["one", "two"]);
 * console.log(state()); // ["one", "two"]
 * mutate(vals => vals.push("three"));
 * console.log(state()); // ["one", "two", "three"]
 * ```
 * @param defaultValue Initial value of the state. If not set, will default to an empty array
 * @returns
 */
export function createArraySignal<T>(defaultValue: T[] = []): ArraySignal<T> {
	const [value, setValue] = createSignal<T[]>(defaultValue, { equals: () => false });

	const mutator = (mutator: (value: T[]) => void) => {
		mutator(value());
		setValue(value());
	};

	return [value, mutator];
}

/**
 * An element reference used in component props
 */
export type PropsRef<T> = T | ((ref: T) => void) | undefined;

/**
 * Creates a signal that intercepts HTMLElement refs in component properties
 * ```tsx
 * interface props = {ref: PropsRef<HTMLDivElement>}
 * const [state, setState] = createPropRefSignal(props.ref);
 * return <div ref={setState}></div>;
 * ```
 * For more information about property refs, see {@link https://docs.solidjs.com/concepts/refs Refs}
 * @param propsRef The props.ref value you want to set
 * @returns The [getter, setter] of the referenced HTMLElement
 */
export function createPropsRefSignal<T>(propsRef: () => PropsRef<T>): [Accessor<T | undefined>, Setter<T | undefined>] {
	const [value, setValue] = createSignal<T>();
	createEffect(() => (propsRef as (value: T | undefined) => void)?.(value()));
	return [value, setValue];
}

/**
 * Creates an accessor that returns true when the component layout is complete
 * ```ts
 * const layoutComplete = createLayoutComplete();
 * ```
 * @returns An accessor that is true when the component layout is complete
 */
export function createLayoutComplete() {
	const [layoutComplete, setLayoutComplete] = createSignal(false);
	onMount(() => requestAnimationFrame(() => requestAnimationFrame(() => setLayoutComplete(true))));
	return layoutComplete;
}

export function useRenderMount(action: () => void) {
	onMount(() => requestAnimationFrame(() => requestAnimationFrame(action)));
}

/**
 * Creates a memo with that must be tracked and disposed of manually.
 * ```tsx
 * const [memo, disposeMemo] = createDisposableMemo(() => props.value + 1);
 * ```
 * NOTE: This will not be automatically tracked or cleaned up. It should only be used in cases where manual unsubscriptions are required.
 * @param fn The memo update function
 * @param initialValue The initial value (optional)
 * @returns
 */
export function createDisposableMemo<T>(fn: (v: T) => T, initialValue?: T): [Accessor<T>, () => void] {
	let disposer: () => void;
	let value: Accessor<T>;

	createRoot((dispose) => {
		disposer = dispose;
		// eslint-disable-next-line solid/reactivity
		value = createMemo<T>((v: T) => fn(v), initialValue as T);
	});

	return [value!, disposer!];
}

export function createPolledSignal<T>(fn: (prev: T | undefined) => T, intervalMs: number): [Accessor<T>, () => void] {
	const [value, setValue] = createSignal<T>(fn(undefined));
	let timerHandle: number | undefined = undefined;

	onMount(() => {
		timerHandle = window.setInterval(() => {
			setValue(fn);
		}, intervalMs);
	});

	function cleanUp() {
		if (timerHandle) {
			window.clearInterval(timerHandle);
			timerHandle = undefined;
		}
	}

	onCleanup(() => cleanUp());

	return [value, cleanUp];
}

/**
 * Creates a signal useful for animations
 * @param animationDurationMs Accessor getting the duration of the animation. For manually controlled start/stop, do not set. Default: undefined
 * @param autoStart Should the animation automatically start? Default: false
 * @returns [Accessor(animationTimeElapsed), Accessor(isAnimating), Setter(isAnimating)]
 */
export function createAnimationSignal(
	animationDurationMs?: Accessor<number>,
	autoStart = false,
): [Accessor<number>, Accessor<boolean>, Setter<boolean>] {
	let lastAnimationTime = 0;
	const [animationTimeElapsed, setAnimationTimeElapsed] = createSignal(0);
	const [isAnimating, setIsAnimating] = createSignal(false);

	createEffect(
		on(
			() => isAnimating(),
			(shouldStart) => {
				if (shouldStart) {
					setAnimationTimeElapsed(0);
					requestAnimationFrame((time) => {
						lastAnimationTime = time;
						if (isAnimating()) {
							requestAnimationFrame(animate);
						}
					});
				}
			},
		),
	);

	function animate(timestamp: number) {
		if (isAnimating()) {
			const timeDelta = timestamp - lastAnimationTime;
			setAnimationTimeElapsed((t) => t + timeDelta);

			if (animationDurationMs && animationTimeElapsed() >= animationDurationMs()) {
				setIsAnimating(false);
			} else {
				requestAnimationFrame(animate);
			}
		}

		lastAnimationTime = timestamp;
	}

	if (autoStart) {
		setIsAnimating(true);
	}

	onCleanup(() => setIsAnimating(false));

	return [animationTimeElapsed, isAnimating, setIsAnimating];
}

export function createElementEventSignal<T extends keyof HTMLElementEventMap, E extends HTMLElementEventMap[T]>(
	element: HTMLElement,
	eventName: T,
): Accessor<E | undefined> {
	const [event, setEvent] = createSignal<E>();
	const listener = (event: E) => setEvent(() => event);

	element.addEventListener(eventName, listener);

	onCleanup(() => element?.removeEventListener(eventName, listener));

	return event;
}

export function createWindowEventSignal<T extends keyof WindowEventMap, E extends WindowEventMap[T]>(
	eventName: T,
): Accessor<E | undefined> {
	const [event, setEvent] = createSignal<E>();
	const listener = (event: E) => setEvent(() => event);
	window.addEventListener(eventName, listener);

	onCleanup(() => window.removeEventListener(eventName, listener));
	return event;
}

/**
 * Creates a signal that only updates after a period of time has elapsed without changing
 * @param fn
 * @param intervalMs
 * @returns [Accessor<T>, Setter<T>, Accessor<T>, Accessor<T>] = [debounced value, live setter, is debouncing, live value]
 */
export function createDebouncedSignal<T>(
	intervalMs: number,
	initialValue: T,
): [Accessor<T>, Setter<T>, Accessor<boolean>, Accessor<T>] {
	const [value, setValue] = createSignal(initialValue);
	const [debouncedValue, setDebouncedValue] = createSignal(initialValue);
	const isDebouncing = createMemo(() => value() != debouncedValue());
	let timeoutId: number | undefined;

	createEffect(
		on(
			() => value(),
			(value) => {
				if (timeoutId) {
					clearTimeout(timeoutId);
				}

				timeoutId = window.setTimeout(() => {
					setDebouncedValue(() => value);
				}, intervalMs);
			},
		),
	);

	onCleanup(() => clearTimeout(timeoutId));

	return [debouncedValue, setValue, isDebouncing, value];
}

/**
 * Reactive utility to add a window event listener that automatically cleans up on component unmount
 * @param type The type of the window event
 * @param listener The event listener function
 * @param options Optional event listener options
 */
export function useWindowListener<K extends keyof WindowEventMap>(
	type: K,
	listener: (this: Window, ev: WindowEventMap[K]) => any, //eslint-disable-line @typescript-eslint/no-explicit-any -- Window event listeners can have any return type
	options?: boolean | AddEventListenerOptions,
) {
	if (typeof window !== "undefined") {
		window.addEventListener(type, listener, options);
		onCleanup(() => {
			window.removeEventListener(type, listener, options);
		});
	}
}
